Given a proper and lower semicontinuous function $f:\mathbb{R}^n\rightarrow\overline{\mathbb{R}} := (-\infty,\infty]$, we denote its domain as $\dom\,f=\{x:f(x)<\infty\}$. The Fenchel conjugate function of $f$ is defined as $f^*(y):=\sup\{\langle x,y\rangle - f(x):x\in\mathbb{R}^n\}$. For a set $\mathcal{S}\subset\mathbb{R}^n$, we use ${\rm cl\,\mathcal{S}}$ to denote its closure, ${\rm int}\,\mathcal{S}$ to denote the set of its interior points, and ${\rm conv}(\cS)$ to denote its convex hull. A function $f:\cS\rightarrow\R$ is said to be of class ${\cC}^k(\mathcal{S})$ if it is $k$ times differentiable and the $k$-th derivative is continuous on $\mathcal{S}$. When there is no ambiguity regarding the domain, we simply use the notation ${\cC}^k$. We let $\mathcal{C}(A,B)$ be the set of continuous mappings from set $A$ to set $B$. We use $\|\cdot\|$ to denote the Euclidean norm for vectors and the Frobenius matrix norm for matrices. The $d$-dimensional unit ball is denoted by $\mathbb{B}^d$. The distance between a point $w$ and a set $A$ is denoted by $\dist(w,A):=\inf\{\|w-u\|:\;u\in A\}$. We use the convention $\dist(w,\emptyset):=\infty$. {The Minkowski sum of two sets $A$ and $B$ is denoted as 
$A+B:=\{u+v:\;u\in A,\;v\in B\}$. We use $\alpha A:=\{\alpha u:\;u\in A\}$ to denote the scaled set of $A$ by a given scalar $\alpha$.} For a positive sequence $\{\eta_k\}$, we define $\lambda_\eta(0):=0$, $\lambda_\eta(k):=\sum_{i=0}^{k-1}\eta_i$ for $k\geq1$, and $\Lambda_\eta(t):=\sup\{k:\lambda_\eta(k)\leq t\}$. In other word, $\Lambda_\eta(t)=k$ if and only if $\lambda_\eta(k)\leq t<\lambda_\eta(k+1)$. {Given a convex function $g$, we say $x$ is a $\nu$-optimal solution of the problem $\min_{x\in\R^n}\;g(x)$ if ${\rm dist}(0,\partial g(x))\leq\nu$.}


\begin{definition}\label{graph-def}
Let $\mathcal{X}\subset\mathbb{R}^n$. A set-valued mapping $S:\mathcal{X}\rightrightarrows\mathbb{R}^m$ is said to be closed if its graph, defined by
\[
{\rm graph}(S):=\{(x,y)\in\R^n\times\R^m:y\in S(x)\}
\]
is a closed set in $\R^n\times\R^m$. Give a nonnegative $\delta$, the $\delta$-perturbed set of $S$ is defined by 
\[
S^\delta(x):=\cup_{\{y\in\R^n:\norm{y-x}\leq\delta\}}\left(S(y)+\delta\mathbb{B}^m\right).
\]
$S:\mathcal{X}\rightrightarrows\mathbb{R}^m$ is called outer semicontinuous at $\bar{x}\in\mathcal{X}$ if for any sequence $x_i\overset{\mathcal{X}}{\rightarrow}\bar x$ and $v_i\in S(x_i)$ converging to some $\bar{v}\in\mathbb{R}^m$, we have $\bar{v}\in S(\bar{x})$. $S$ is said to be outer semicontinuous if it is outer semicontinuous everywhere over $\mathcal{X}$.
\end{definition}

\begin{definition}\label{Bregman-distance-def}
(Kernel function and Bregman distance over $\R^n$).  A function $\phi:\R^n\rightarrow\R$ is called a kernel function over $\R^n$, if $\phi$ is convex and $\phi\in\cC^1(\R^n)$. The Bregman distance \cite{bregman1967relaxation} generated by $\phi$ is denoted as $\cD_\phi(x,y):\R^n\times\R^n\rightarrow[0,+\infty)$, where
\[
\cD_\phi(x,y)=\phi(x)-\phi(y)-\inprod{\nabla\phi(y)}{x-y}.
\]
\end{definition}

\begin{definition}\label{Legendre}
(Legendre kernel over $\R^n$). Let $\phi$ be a kernel function over $\R^n$, such that $\lim_{k\rightarrow\infty}\|\nabla\phi({x_k})\|=\infty$ whenever $\{{x_k}\}_{k\in\mathbb N}$ satisfies $\lim_{k\rightarrow\infty}\norm{x_k}=\infty$. The function $\phi$ is called a Legendre function over $\R^n$ if it is also {strictly} convex on $\R^n$.
\end{definition}

We end this subsection by introducing the concept of functional convergence over any compact set, as discussed in literature such as \cite{benaim2005stochastic,duchi2018stochastic,davis2020stochastic}. Given a sequence of mappings $f_n\in\cC(\mathbb{R}_+,\mathbb{R}^n)$, we say that $f_n$ converges to $f$ in $\cC(\R_+,\R^n)$ if, for any $T>0$, it holds that
\[
\lim_{n\rightarrow\infty}\sup_{t\in[0,T]}\|f_n(t)-f(t)\|=0.
\]


\begin{equation}
    \label{Eq:Breg_DI}
    \frac{d}{dt}\nabla\phi(x(t))\in-\mathcal{H}(x(t)), \text{ for almost all $t\geq0$.}
\end{equation}

Any absolutely continuous solution to \eqref{Eq:Breg_DI} is termed a trajectory of \eqref{Eq:Breg_DI}. The stable set of \eqref{Eq:Breg_DI} is defined as 
\begin{equation}
\label{eq:def_stable_set}
\cH^{-1}(0):=\{x\in\R^n:0\in\cH(x)\}.
\end{equation}

\begin{equation}
   \label{Eq:Breg_general_iterative}  \nabla\phi(x_{k+1})=\nabla\phi(x_k)-\eta_k(d_k+\xi_k),
\end{equation}

where $d_k$ is an evaluation of $\cH(x_k)$ with possible inexactness, and $\xi_k$ is the stochastic noise. This formulation, referred to as the general Bregman-type method, is notable for the versatile choices of $\phi$ and $\cH$. For the Bregman counterpart of the interpolated process \eqref{Eq:x(t)_def} in the Euclidean setting, we introduce the linear interpolation for the dual sequence $\{\nabla\phi(x_k)\}$:
\begin{equation}
 \label{Eq:interpolation}
 x(t):=\nabla\phi^*\left(\nabla\phi(x_k)+\frac{t-\lambda_\eta(k)}{\eta_k}(\nabla\phi(x_{k+1})-\nabla\phi(x_k))\right),\;t\in[\lambda_\eta(k),\lambda_\eta(k+1)). 
\end{equation}

If $\phi^*\in\cC^1(\R^n)$, then \eqref{Eq:interpolation} is well defined. Let $x^t(\cdot)$ denote the time-shifted curve of the interpolated process, i.e. $x^t(\cdot)=x(t+\cdot)$. We make the following assumptions on \eqref{Eq:Breg_DI} and \eqref{Eq:Breg_general_iterative} to ensure that the iterative sequence generated by \eqref{Eq:Breg_general_iterative} tracks a trajectory of \eqref{Eq:Breg_DI} asymptotically.
\begin{assumption}
\label{Assumption: DI}
    \begin{enumerate}
        \item {$\phi$ is a supercoecive Legendre kernel function over $\R^n$}, and $\nabla\phi$ is differentiable almost everywhere.
        \item The sequences $\{x_k\}$, $\{\nabla\phi(x_k)\}$ and $\{d_k\}$ are uniformly bounded.
        \item The stepsize $\{\eta_k\}$ satisfies $\sum_{k=0}^\infty\eta_k=\infty$ and $\lim_{k\rightarrow\infty}\eta_k=0$.
        \item For any $T>0$, the noise sequence $\{\xi_k\}$ satisfies 
        \begin{equation}
            \lim_{s\rightarrow\infty}\sup_{s\leq i\leq\Lambda_\eta(\lambda_\eta(s)+T)}\norm{\sum_{k=s}^i\eta_k\xi_k}=0.
            \label{Eq:noise_cond}
        \end{equation}       
        \item The set-valued mapping $\mathcal{H}$ has a closed graph. Additionally, for any unbounded increasing sequence $\{k_j\}$ such that $\{x_{k_j}\}$ converges to $\bar x$, it holds that 
        \begin{equation}
            \lim_{N\rightarrow\infty}{\rm dist}\left(\frac{1}{N}\sum_{j=1}^Nd_{k_j},\mathcal{H}(\bar x)\right)=0.
        \end{equation}
    \end{enumerate}
\end{assumption}

\begin{remark}
    \label{rmk:assumption_DI}
    \begin{enumerate}
        \item {If the Legendre function $\phi$ is supercoecive, i.e. $\lim_{\|u\|\rightarrow\infty}\frac{\phi(u)}{\|u\|}=\infty$, then by \cite[Theorem 26.5,\,Corollary 13.3.1]{rockafellar1997convex}, $\phi^*\in\cC^1(\R^n)$ is strictly convex, and $(\nabla\phi)^{-1}=\nabla\phi^*$.}
        \item Uniform boundedness of either $\{x_k\}$ or $\{\nabla\phi(x_k)\}$ may suffice under mild conditions. For example, if $\phi$ is locally strongly convex, then the uniform boundedness of $\{\nabla\phi(x_k)\}$ implies the uniform boundedness of $\{x_k\}$. Conversely, if $\nabla\phi$ is locally Lipschitz continuous, then the uniform boundedness of $\{x_k\}$ leads to the uniform boundedness of $\{\nabla\phi(x_k)\}$.
        \item For a martingale difference noise sequence $\{\xi_k\}$,  i.e. $\E[\xi_{k+1}|\cF_k]=0$ holds  almost surely,  as shown in \cite{benaim2005stochastic}, \eqref{Eq:noise_cond} can be ensured almost surely under one of the following conditions:
        \begin{enumerate}
            \item Uniform boundedness of $\{\xi_k\}$ with $\eta_k=o\left(\frac{1}{\log k}\right)$ as utilized in \cite{castera2021inertial,xiao2023adam,xiao2023convergence}.
            \item Variance-bounded $\{\xi_k\}$, i.e. $\E[\norm{\xi_{k+1}}^2|\cF_k]\leq\sigma^2$ for some $\sigma>0$, and square-summable $\{\eta_k\}$, i.e. $\sum_{k=0}^\infty\eta_k^2<\infty$, as employed in \cite{davis2020stochastic}.
        \end{enumerate}
        \item Assumption \ref{Assumption: DI}(5) describes how $d_k$ approximates $\cH(x_k)$. This assumption is quite mild. A sufficient condition for it hold is that $d_k\in\cH^{\delta_k}(x_k)$ with $\lim_{k\to\infty}\delta_k=0$. 
    \end{enumerate}
\end{remark}

\begin{assumption}\label{assumption_Sard_Lyapunov}
 There exists a continuous function $\Psi:\R^n\to\R$, such that the following conditions hold:
 \begin{enumerate}
     \item (Weak Morse-Sard). The set 
     {$\{\Psi(x): \mbox{for $x$ such that $0\in\cH(x)$} \}$}  has empty interior in $\R$.
     \item (Lyapunov function). $\Psi$ is lower bounded, i.e. $\liminf_{x\in\R^n}\Psi(x)>-\infty$. For any trajectory $z(t)$ of the differential inclusion \eqref{Eq:Breg_DI} with $z(0)\notin\cH^{-1}(0)$,  there exists $T > 0$ such that
     \[
     \Psi(z(T))<\sup_{t\in[0,T]}\Psi(z(t))\leq\Psi(z(0)).
     \]
 \end{enumerate}
\end{assumption}

To establish under Assumption \ref{Assumption: DI} that, the discrete sequence generated by the general Bregman-type method \eqref{Eq:Breg_general_iterative} tracks a trajectory of the differential inclusion \eqref{Eq:Breg_DI}, we introduce a piecewise constant mapping $d(\cdot)$ defined by $d(s)=d_k$ for any $s\in[\lambda_\eta(k),\lambda_\eta(k+1))$. We also define a time-shifted solution $x_t(\cdot)$ to the following ordinary differential equation:
\[
\frac{d}{ds}\nabla\phi({x_t(s)})=-d(s)\;for\;all\;s\geq t,\;\mbox{with initial condition}\;\nabla\phi(x_t(t))=\nabla\phi(x(t)).
\]
The following lemma suggests that the interpolated process $x(t)$ defined by \eqref{Eq:interpolation} asymptotically approximates this time-shifted solution.
We remind the reader to note the difference between $x_t(\cdot)$ and $x^t(\cdot)$.

