\begin{theorem}\label{convergence-thm-func-val}
Suppose Assumptions \ref{Assumption: DI} and \ref{assumption_Sard_Lyapunov} hold. Then any cluster point of $\{x_k\}$ lies in $\mathcal{H}^{-1}(0)$ and the function values $\{\Psi(x_k)\}_{k\geq1}$ converge.
\end{theorem}

