\begin{theorem}\label{subsequential-thm}
Suppose Assumption \ref{Assumption: DI} holds. Then, for any sequence $\{\tau_k\}_{k=1}^\infty\subset\R_+$, the set of shifted sequence $\{\nabla\phi(x^{\tau_k}(\cdot))\}_{k=1}^\infty$ is relatively compact in $\mathcal{C}(\R_+,\R^n)$. If $\lim_{k\rightarrow\infty}\tau_k=\infty$, then any cluster point $\bar y(\cdot)$ of $\{\nabla\phi(x^{\tau_k}(\cdot))\}_{k=1}^\infty$ belongs to $\mathcal{C}(\R+,\R^n)$. Define $\bar x(\cdot):=\nabla\phi^*(\bar y(\cdot))$. Then there exists a measurable $\bar d(t)\in\mathcal{H}(\bar x(t))$ satisfying 
\begin{equation}
\nabla\phi(\bar x(t))=\nabla\phi(\bar x(0))-\int_{0}^t\bar d(\tau)d\tau\quad for\;all\;t\geq0.
\label{Eq:DI_int_form}
\end{equation}
Equivalently, we have 
\[
\frac{d}{dt}\nabla\phi(\bar x(t))\in-\mathcal{H}(\bar x(t)),\;for\;almost\;all\;t\geq0.
\]
\end{theorem}

\begin{proof}
{Since $\{x_k\}$ is bounded, let $x^*$ be any cluster point of $\{x_k\}$, and ${\lim_{i\rightarrow\infty}}{x_{k_i}}=x^*$. By Theorem \ref{subsequential-thm}, up to a subsequence, $\nabla\phi(x^{\lambda_\eta(k_i)}(\cdot))\rightarrow\nabla\phi(\bar x(\cdot))$ for some $\bar x(\cdot)\in\cC(\R_+,\R^n)$. Note that $x_{{k_i}}=x^{\lambda_\eta(k_i)}(0)$, so we have 
\[
\begin{aligned}
\norm{\bar x(0)-x^*}\leq&\limsup_{i\rightarrow\infty}\left(\norm{\bar x(0)-x^{\lambda_\eta(k_i)}(0)}+\norm{x^{\lambda_\eta(k_i)}(0)-x_{k_i}}+\norm{x_{k_i}-x^*}\right)\\
=&\limsup_{i\rightarrow\infty}\left(\norm{\nabla\phi^*(\nabla\phi(\bar x(0)))-\nabla\phi^*(\nabla\phi(x^{\lambda_\eta(k_i)}(0)))}+\norm{x^{\lambda_\eta(k_i)}(0)-x_{k_i}}+\norm{x_{k_i}-x^*}\right)\\
=&0,
\end{aligned}
\]
where the last equality comes from the continuity of $\nabla\phi^*$.} Hence $\bar x(0)=x^*$. Suppose $x^*\notin \mathcal{H}^{-1}(0)$, then by Assumption \ref{assumption_Sard_Lyapunov}, there exists $T>0$, such that 
\[
\Psi(\bar x(T))<\sup_{t\in[0,T]}\Psi(\bar x(t))\leq\Psi(x^*).
\]
On the other hand, by Lemma \ref{prop:nonescape}, $\Psi(x(t))$ converges {as $t\to\infty$}. Therefore, we obtain
\[
\Psi(\bar x(T))={\lim_{i\rightarrow\infty}}\Psi(x^{\lambda_\eta(k_i)}(T))=
{\lim_{i\rightarrow\infty}}
\Psi(x({\lambda_\eta(k_i)}+T))=\lim_{t\rightarrow\infty}\Psi(x(t))=\Psi(x^*), 
\]
which leads to a contradiction. Therefore, $0\in \mathcal{H}(x^*)$. This completes the proof.
\end{proof}

\begin{lemma}
\label{le:shift convergence}
Suppose Assumption \ref{Assumption: DI} holds, then for any $T>0$, it holds that
\begin{equation}
\lim_{t\rightarrow\infty}\sup_{s\in[t,t+T]}\|\nabla\phi(x(s))-\nabla\phi(x_t(s))\|=0.
\label{asymptotic-lemma}
\end{equation}
\end{lemma}

\begin{proof}
Fix an arbitrary $s\in[t,t+T]$, let $\tau_t=\Lambda_\eta(t)$, $\tau_s=\Lambda_\eta(s)$. By the definition of $x_t(\cdot)$, we have
\[
\begin{aligned}
&\nabla\phi(x_t(s))=\nabla\phi(x(t))-\int_{t}^{\lambda_\eta(\tau_t)}d(u)du-\int_{\lambda_\eta(\tau_t)}^{\lambda_\eta(\tau_s)}d(u)du-\int_{\lambda_\eta(\tau_s)}^s d(u)du\\
=&\nabla\phi(x(\lambda_\eta(\tau_t)))-\sum_{i=\tau_t}^{\tau_s-1}\eta_id_i+\left(\nabla\phi(x(t))-\int_t^{\lambda_\eta(\tau_t)}d(u)du-\nabla\phi(x(\lambda_\eta(\tau_t)))\right)-\int_{\lambda_\eta(\tau_s)}^s d(u)du\\
=&\nabla\phi(x({\lambda_\eta(\tau_s})))+\sum_{i=\tau_t}^{\tau_s-1}\eta_i\xi_i+\left(\nabla\phi(x(t))-\int_t^{\lambda_\eta(\tau_t)}d(u)du-\nabla\phi(x(\lambda_\eta(\tau_t)))\right)-\int_{\lambda_\eta(\tau_s)}^s d(u)du\\
=&\nabla\phi(x(s))+\sum_{i=\tau_t}^{\tau_s-1}\eta_i\xi_i+\left(\nabla\phi(x(t))-\int_t^{\lambda_\eta(\tau_t)}d(u)du-\nabla\phi(x(\lambda_\eta(\tau_t)))\right)\\
&+\left(\nabla\phi(x(\lambda_\eta(\tau_s)))-\int_{\lambda_\eta(\tau_s)}^sd(u)du-\nabla\phi(x(s))\right).
\end{aligned}
\]
Note that
\[
\begin{aligned}
&\norm{\nabla\phi(x(t))-\int_t^{\lambda_\eta(\tau_t)}d(u)du-\nabla\phi(x(\lambda_\eta(\tau_t)))}\\
\leq&{\|\nabla\phi(x(t))-\nabla\phi(x(\lambda_\eta(\tau_t)))\|}
+\int_t^{\lambda_\eta(\tau_t)}\|d(u)\|du
\\
 \leq&{\|\nabla\phi(x(\lambda_\eta(\tau_t+1)))-\nabla\phi(x(\lambda_\eta(\tau_t)))\|}
+\int_t^{\lambda_\eta(\tau_t)}\|d(u)\|du
\\
 \leq&\eta_{\tau_t}(\|\xi_{\tau_t}\|+2\|d_{\tau_t}\|),
 \end{aligned}
\]
and similarly 
$
\big\|\nabla\phi(x(\lambda_\eta(\tau_s)))-\int_{\lambda_\eta(\tau_s)}^sd(u)du-\nabla\phi(x(s))\big\|\leq\eta_{\tau_s}(\|\xi_{\tau_s}\|+2\|d_{\tau_s}\|).
$
By Assumption \ref{Assumption: DI}, we 
have that $\lim\sup\limits_{t\rightarrow\infty}\eta_{\tau_t}(\|\xi_{\tau_t}\|+2\|d_{\tau_t}\|)=0$, $\lim\sup\limits_{s\rightarrow\infty}\eta_{\tau_s}(\|\xi_{\tau_s}\|+2\|d_{\tau_s}\|)=0$, and $\lim\limits_{t\rightarrow\infty}\sup\limits_{s\in[t,t+T]}\sum_{i=\tau_t}^{\tau_s-1}\eta_i\xi_i=0$. Therefore, it holds that $\lim\limits_{t\rightarrow\infty}\sup\limits_{s\in[t,t+T]}\|\nabla\phi(x(s))-\nabla\phi(x_t(s))\|=0$, which completes the proof.
\end{proof}

\noindent{\textit{Proof of Theorem \ref{subsequential-thm}
.}} By the definition of $x_t(\cdot)$, it follows that $\nabla\phi(x_t(s))=\nabla\phi(x(t))-\int_t^s y(u)du$, for all $s\geq t$. By the boundedness of $y(s)$, Arzel$\grave{a}$-Ascoli's theorem \cite{rudin1953principles} ensures that $\{\nabla\phi(x_t(t+\cdot))\}_{t\in\R_+}$ is relatively compact in $\cC(\R_+,\R^n)$. For any subset $\{\tau_k\}\subset\R_+$, we consider the sequence $\{\nabla\phi(x^{\tau_k}(\cdot))\}_{k\in\mathbb{N}_+}$. There are two cases to consider. Case (i): the sequence $\{\tau_k\}$ has a cluster point $t$. Without loss of generality, assume that $\lim_{k\rightarrow\infty}\tau_k=t$. By the definition of $x(\cdot)$ {in \eqref{Eq:interpolation}} and uniform boundedness assumption, it holds that  $\nabla\phi(x(\cdot))$ is Lipschitz continuous. Thus, $\nabla\phi(x^{\tau_k}(\cdot))$ converges to $\nabla\phi(x^t(\cdot))$ in $\cC(\R_+,\R^n)$. Case (ii): $\lim_{k\rightarrow\infty}\tau_k=\infty$. Suppose that $\nabla\phi(x^{\tau_k}(\cdot))$ does not has any cluster point in $\cC(\R_+,\R^n)$. Since $\{\nabla\phi(x_{\tau_k}(\tau_k+\cdot))\}$ is relatively compact in $\cC(\R_+,\R^n)$, without loss of generality, we assume that $\lim_{k\rightarrow\infty}\nabla\phi(x_{\tau_k}(\tau_k+\cdot))=\bar y(\cdot)$. Then, for any compact set $C\subset\R_+$, it follows from Lemma \ref{le:shift convergence} that
\[
\begin{aligned}
&\lim_{k\rightarrow\infty,s\in C}\norm{\nabla\phi(x^{\tau_k}(s))-\bar y(s)}\\
\leq&\lim_{k\rightarrow\infty,s\in C}\norm{\nabla\phi(x^{\tau_k}(s))-\nabla\phi(x_{\tau_k}(\tau_k+s))}+\lim_{k\rightarrow\infty,s\in C}\norm{\nabla\phi(x_{\tau_k}(\tau_k+s))-\bar y(s)}=0,
\end{aligned}
\]
which contradicts that $\nabla\phi(x^{\tau_k}(\cdot))$ does not has any cluster point in $\cC(\R_+,\R^n)$. Thus, in both cases, $\{\nabla\phi(x^{\tau_k}(\cdot))\}$ is relatively compact in $\cC(\R_+,\R^n)$. Because $\{\tau_k\}$ is an arbitrary subset in $\R_+$, we have that $\{\nabla\phi(x^t(\cdot))\}$ is relatively compact in $\cC(\R_+,\R^n)$. 

Next, we aim to construct a trajectory of the differential inclusion. Define the shifts $d^t(\cdot)=d(t+\,\cdot)$. Consider $\{\tau_k\}$ satisfying $\tau_k\rightarrow\infty$, and fix $T>0$. Without loss of generality, we assume that $\nabla\phi(x^{\tau_k}(\cdot))$ converges to $\bar y(\cdot)$ in $\cC(\R_+,\R^n)$, otherwise, we choose its convergent subsequence. The set $\mathcal{Y}_T:=\{d^{\tau_k}(s),s\in[0,T]\}_{k\in\mathbb{N}}\subset L^2([0,T])$ is bounded. Therefore, it follows from the Banach-Alaoglu theorem \cite{rudin1991functional} that $\cY_T$ is weakly sequentially compact, i.e. there exists a subsequence $\{\tau_{k_j}\}$ and $\bar y(\cdot)\in L^2([0,T])$ such that $d^{\tau_{k_j}}(\cdot)\rightarrow\bar d(\cdot)$ weakly in $L^2([0,T])$. On the other hand, by Lemma \ref{le:shift convergence}, we have $\nabla\phi(x_{\tau_{k_j}}(\tau_{k_j}+\cdot))$ 
converges to $\bar y(\cdot)$ in $\cC(\R_+,\R^n)$. For any $\tau\in[0,T]$, by the definition of $x_t(\cdot)$, we have
\[
\nabla\phi(x_t(t+\tau))=\nabla\phi(x_t(t))-\int_0^\tau d^t(s)ds.
\]
Setting $t=\tau_{k_j}$ and taking the limit as $k_j\rightarrow\infty$, we deduce that
\[
\bar y(\tau)=\bar y(0)-\int_0^\tau\bar d(s)ds.
\]
Let $\bar x(\cdot)=\nabla\phi^*(\bar y(\cdot))$, since $T>0$ is arbitrary, we get \eqref{Eq:DI_int_form}. 

The remaining step is to verify that $\bar d(s)\in\mathcal{H}(\bar x(s))$ for almost all $s\geq0$. We again fix an arbitrary $T > 0$. Given that $\mathcal{Y}_T\subset L^2([0,T])$ is bounded, the Banach-Saks theorem \cite{rudin1991functional} implies that for ${\tau_k}$ (choosing a subsequence if necessary), $\frac{1}{N}\sum_{k=1}^Nd^{\tau_k}(s)$ strongly converges to $\bar d(s)$ in $L^2([0,T])$ . By the definition of $d(\cdot)$, we have $d^{\tau_k}(s)=d_{\Lambda_\eta(\tau_k+s)}$. Now for any $s\in[0,T]$, we have
\[
\begin{aligned}
    &\|\nabla\phi(x(\lambda_\eta(\Lambda_\eta(\tau_k+s))))-\nabla\phi(\bar x(s))\|\\
    \leq&\|\nabla\phi(x(\lambda_\eta(\Lambda_\eta(\tau_k+s))))-\nabla\phi(x(\tau_k+s))\|+\|\nabla\phi(x^{\tau_k}(s))-\nabla\phi(\bar x(s))\|\\
    \leq&\|\nabla\phi(x(\lambda_\eta(\Lambda_\eta(\tau_k+s)+1)))-\nabla\phi(x(\lambda_\eta(\Lambda_\eta(\tau_k+s))))\|+\|\nabla\phi(x^{\tau_k}(s))-\nabla\phi(\bar x(s))\|\\
    \leq&\eta_{\Lambda_\eta(\tau_k+s)}(\|\xi_{\Lambda_\eta(\tau_k+s)}\|+\|d_{\Lambda_\eta(\tau_k+s)}\|)+\|\nabla\phi(x^{\tau_k}(s))-\nabla\phi(\bar x(s))\|,
\end{aligned}
\]
which converges to zero as $k\rightarrow\infty$. By the continuity of $\nabla\phi^*$, we have that $x(\lambda_\eta(\Lambda_\eta(\tau_k+s)))$ converges to $\bar x(s)$ in $\cC(\R_+,\R^n)$. By Assumption \ref{Assumption: DI}, for almost any $s\in[0,T]$, we have
\[
\begin{aligned}
{\rm dist}(\bar d(s),\mathcal{H}(\bar x(s)))&\leq\bigg\|\frac{1}{N}\sum_{k=1}^Nd^{\tau_k}(s)-\bar d(s)\bigg\|+{\rm dist}\left(\frac{1}{N}\sum_{k=1}^Nd^{\tau_k}(s),\mathcal{H}(\bar x(s))\right)\\
=&\bigg\|\frac{1}{N}\sum_{k=1}^Nd^{\tau_k}(s)-\bar d(s)\bigg\|+
{\rm dist}\left(\frac{1}{N}\sum_{k=1}^Nd_{\Lambda_\eta(\lambda_\eta(\tau_k+s))},\mathcal{H}(\bar x(s))\right)\rightarrow0.
\end{aligned}
\]
Since $T$ is arbitrary and $\mathcal{H}(\bar x(s))$ is a closed set, we conclude that $\bar d(s)\in\mathcal{H}(\bar x(s))$ for almost all $s\geq0$. This completes the proof.\qed


\begin{lemma}
\label{le:liminf_limsup}
Suppose Assumption \ref{Assumption: DI} is satisfied. Then, it holds that
\begin{equation}
    \label{Eq:liminf_limsup}
    \liminf_{t\rightarrow\infty}\Psi(x(t))=\liminf_{k\rightarrow\infty}\Psi(x_k),\quad \limsup_{t\rightarrow\infty}\Psi(x(t))=\limsup_{k\rightarrow\infty}\Psi(x_k).
\end{equation}
\end{lemma}

\begin{proof}
For simplicity, we only prove the case for $\liminf$, the argument for $\limsup$ follows similarly. By Assumption \ref{Assumption: DI}, we have that 
\begin{equation}
\lim_{k\rightarrow\infty}\|\nabla\phi(x_{k+1})-\nabla\phi(x_k)\|=0.
\label{Eq:succ_gap_convergence}
\end{equation}
Let $\tau_i\rightarrow\infty$ be an arbitrary sequence with $x(\tau_i)\rightarrow x^*$. By the definition of $\lambda_\eta$ and $\Lambda_\eta$, it follows that
\[
\begin{aligned}
\|\nabla\phi(x_{\Lambda_\eta(\tau_i)})-\nabla\phi(x^*)\|\leq&\|\nabla\phi(x_{\Lambda_\eta(\tau_i)})-\nabla\phi(x(\tau_i))\|+\|\nabla\phi(x(\tau_i))-\nabla\phi(x^*)\|\\
\leq&\|\nabla\phi(x_{\Lambda_\eta(\tau_i)})-\nabla\phi(x_{\Lambda_\eta(\tau_i)+1})\|+\|\nabla\phi(x(\tau_i))-\nabla\phi(x^*)\|.
\end{aligned}
\]
The right-hand side converges to zero. By Remark \ref{rmk:assumption_DI}.1, we have that $\Psi\circ\nabla\phi^*$ is continuous, so $\lim_{i\rightarrow\infty}\Psi(x_{\Lambda_\eta(\tau_i)})=\lim_{i\rightarrow\infty}\Psi\circ\nabla\phi^*\circ\nabla\phi(x_{\Lambda_\eta(\tau_i)})=\Psi\circ\nabla\phi^*\circ\nabla\phi(x^*)=\Psi(x^*)$. By choosing $\tau_i\rightarrow\infty$ as the sequence realizing $\liminf_{t\rightarrow\infty}\Psi(x(t))$, and assuming without loss of generality that $x(\tau_i)\rightarrow x^*$, we get
\[   \liminf_{k\rightarrow\infty}\Psi(x_k)\leq
\lim_{{i\rightarrow\infty}}\Psi(x_{\Lambda_\eta(\tau_i)})=\Psi(x^*)
=\liminf_{t\rightarrow\infty}\Psi(x(t)).
\]
This completes the proof.
\end{proof}

\begin{lemma}
    \label{prop:nonescape}
    Suppose Assumption \ref{Assumption: DI} and \ref{assumption_Sard_Lyapunov} hold, then function value $\Psi(x(t))$ converges {as $t\to\infty$.}
\end{lemma}

\begin{proof}
Assuming $\liminf_{t\rightarrow\infty}\Psi(x(t))=0$, we define the level set $\cL_r:=\{x\in\R^n:\;\Psi(x)\leq r\}$. Choose any $\epsilon>0$ such that $\epsilon\notin\Psi(\mathcal{H}^{-1}(0))$. The weak Morse-Sard condition in Assumption \ref{Assumption: DI} implies that $\epsilon$ can be chosen arbitrarily small, and Lemma \ref{le:liminf_limsup} implies that there are infinitely many $k$ such that $x_k\in\cL_\epsilon$. For any $x_k\in\cL_\epsilon$, by the continuity of $\Psi$, we have that there exists $\alpha>0$ such that ${\rm dist}(x_k,\R^n\setminus\cL_{2\epsilon})>\alpha$. By \eqref{Eq:succ_gap_convergence}, for sufficiently large $k$, we have that $\norm{x_{k+1}-x_k}<\alpha$. Therefore, for all large $k$, $x_k\in\cL_\epsilon$ implies that $x_{k+1}\in\cL_{2\epsilon}$.
Now, we define the last entrance and the first subsequent exit times,
\begin{equation}
\begin{aligned}
    &k_i=\max\{m\geq j_{i-1}:x_m\in\cL_\epsilon\}, \quad
    &j_i=\min\{m\geq k_i:x_m\in\R^n\setminus\cL_{2\epsilon}\}.
\end{aligned}
\label{Eq:upcross_def}
\end{equation}
We prove that such upcrossing occurs for finite times. Otherwise, if there exists $\{k_i\}$ such that $\lim_{i\rightarrow\infty}k_i=\infty$, then Theorem \ref{subsequential-thm} indicates that, up to a subsequence, $\nabla\phi(x^{\lambda_\eta(k_i)}(\cdot))$ converges to $\nabla\phi(\bar x(\cdot))$, where $\bar x(\cdot)$ is a trajectory of \eqref{Eq:Breg_DI}. By the definition of $k_i$, we have $\Psi(x_{k_i})\leq\epsilon$, $\Psi(x_{k_i+1})>\epsilon$. By \eqref{Eq:succ_gap_convergence} and the continuity of $\Psi\circ\nabla\phi^*$, we have that $\lim_{i\rightarrow\infty}\Psi(x_{k_i})=\lim_{i\rightarrow\infty}\Psi(x_{k_i+1})=\epsilon$. Recall that $x^{\lambda_\eta(k_i)}(0)=x_{k_i}$, therefore, $\Psi(\bar x(0))=\lim_{i\rightarrow\infty}\Psi(x_{k_i})=\epsilon$. Since $\bar x(0)$ is not in the stable set, there exists $T>0$, such that  
\[
\Psi(\bar x(T))<\sup_{s\in[0,T]}\Psi(\bar x(s))\leq\Psi(\bar x(0))=\epsilon.
\]
Then, there exists $\delta>0$, such that $\Psi(\bar x(T))\leq\epsilon-2\delta$. Moreover, for sufficiently large $i$, we have
\[
\sup_{s\in[0,T]}\Psi(x^{\lambda_\eta(k_i)}(s))\leq\sup_{s\in[0,T]}\Psi(\bar x(s))+\sup_{s\in[0,T]}|\Psi(x^{\lambda_\eta(k_i)}(s))-\Psi(\bar x(s))|\leq2\epsilon.
\]
The last inequality comes from the uniform convergence of $\{\nabla\phi(x^{\lambda_\eta(k_i)}(\cdot))\}$ in $\cC(\R_+,\R^n)$. This implies that for all large $i$, $\{x(\lambda_\eta(k_i)+s):s\in[0,T]\}\subset\cL_{2\epsilon}$. Thus it holds that $\lambda_\eta(j_i)>\lambda_\eta(k_i)+T$. Let $l_i=\max\{m:\lambda_\eta(k_i)\leq \lambda_\eta(m)\leq \lambda_\eta(k_i)+T\}$. Then $\|\nabla\phi(x_{l_i})-\nabla\phi(x^{\lambda_\eta(k_i)}(T))\|\leq\|\nabla\phi(x_{l_i})-\nabla\phi(x_{l_i+1})\|\rightarrow0$, and hence $\norm{\nabla\phi(x_{l_i})-\nabla\phi(\bar x(T))}\rightarrow0$ {as $i\to\infty$}. By the continuity of $\Psi\circ\nabla\phi^*$, we have that $\Psi(x_{l_i})\leq\epsilon-\delta$ for all large $i$. By the definition of $k_i$ and $j_i$, we have that $\lambda_\eta(j_i)<\lambda_\eta(l_i)\leq\lambda_\eta(k_i)+T$, which leads to a contradiction. Therefore, for all large $k$, $\Psi(x_k)\leq2\epsilon$. Since $\epsilon$ can be chosen arbitrarily small, it holds that $\lim_{k\rightarrow\infty}\Psi(x_k)=0$. This completes the proof.
\end{proof}

