\label{Eq:succ_gap_convergence}
\end{equation}
Let $\tau_i\rightarrow\infty$ be an arbitrary sequence with $x(\tau_i)\rightarrow x^*$. By the definition of $\lambda_\eta$ and $\Lambda_\eta$, it follows that
\[
\begin{aligned}
\|\nabla\phi(x_{\Lambda_\eta(\tau_i)})-\nabla\phi(x^*)\|\leq&\|\nabla\phi(x_{\Lambda_\eta(\tau_i)})-\nabla\phi(x(\tau_i))\|+\|\nabla\phi(x(\tau_i))-\nabla\phi(x^*)\|\\
\leq&\|\nabla\phi(x_{\Lambda_\eta(\tau_i)})-\nabla\phi(x_{\Lambda_\eta(\tau_i)+1})\|+\|\nabla\phi(x(\tau_i))-\nabla\phi(x^*)\|.
\end{aligned}
\]
The right-hand side converges to zero. By Remark \ref{rmk:assumption_DI}.1, we have that $\Psi\circ\nabla\phi^*$ is continuous, so $\lim_{i\rightarrow\infty}\Psi(x_{\Lambda_\eta(\tau_i)})=\lim_{i\rightarrow\infty}\Psi\circ\nabla\phi^*\circ\nabla\phi(x_{\Lambda_\eta(\tau_i)})=\Psi\circ\nabla\phi^*\circ\nabla\phi(x^*)=\Psi(x^*)$. By choosing $\tau_i\rightarrow\infty$ as the sequence realizing $\liminf_{t\rightarrow\infty}\Psi(x(t))$, and assuming without loss of generality that $x(\tau_i)\rightarrow x^*$, we get
\[   \liminf_{k\rightarrow\infty}\Psi(x_k)\leq
\lim_{{i\rightarrow\infty}}\Psi(x_{\Lambda_\eta(\tau_i)})=\Psi(x^*)
=\liminf_{t\rightarrow\infty}\Psi(x(t)).
\]
This completes the proof.
\end{proof}

For simplicity, we only prove the case for $\liminf$, the argument for $\limsup$ follows similarly. By Assumption \ref{Assumption: DI}, we have that 
\begin{equation}
\lim_{k\rightarrow\infty}\|\nabla\phi(x_{k+1})-\nabla\phi(x_k)\|=0.
\label{Eq:succ_gap_convergence}
\end{equation}

\begin{lemma}
    \label{prop:nonescape}
    Suppose Assumption \ref{Assumption: DI} and \ref{assumption_Sard_Lyapunov} hold, then function value $\Psi(x(t))$ converges {as $t\to\infty$.}
\end{lemma}

\begin{proof}
Assuming $\liminf_{t\rightarrow\infty}\Psi(x(t))=0$, we define the level set $\cL_r:=\{x\in\R^n:\;\Psi(x)\leq r\}$. Choose any $\epsilon>0$ such that $\epsilon\notin\Psi(\mathcal{H}^{-1}(0))$. The weak Morse-Sard condition in Assumption \ref{Assumption: DI} implies that $\epsilon$ can be chosen arbitrarily small, and Lemma \ref{le:liminf_limsup} implies that there are infinitely many $k$ such that $x_k\in\cL_\epsilon$. For any $x_k\in\cL_\epsilon$, by the continuity of $\Psi$, we have that there exists $\alpha>0$ such that ${\rm dist}(x_k,\R^n\setminus\cL_{2\epsilon})>\alpha$. By \eqref{Eq:succ_gap_convergence}, for sufficiently large $k$, we have that $\norm{x_{k+1}-x_k}<\alpha$. Therefore, for all large $k$, $x_k\in\cL_\epsilon$ implies that $x_{k+1}\in\cL_{2\epsilon}$.
Now, we define the last entrance and the first subsequent exit times,
\begin{equation}
\begin{aligned}
    &k_i=\max\{m\geq j_{i-1}:x_m\in\cL_\epsilon\}, \quad
    &j_i=\min\{m\geq k_i:x_m\in\R^n\setminus\cL_{2\epsilon}\}.
\end{aligned}
\label{Eq:upcross_def}
\end{equation}
We prove that such upcrossing occurs for finite times. Otherwise, if there exists $\{k_i\}$ such that $\lim_{i\rightarrow\infty}k_i=\infty$, then Theorem \ref{subsequential-thm} indicates that, up to a subsequence, $\nabla\phi(x^{\lambda_\eta(k_i)}(\cdot))$ converges to $\nabla\phi(\bar x(\cdot))$, where $\bar x(\cdot)$ is a trajectory of \eqref{Eq:Breg_DI}. By the definition of $k_i$, we have $\Psi(x_{k_i})\leq\epsilon$, $\Psi(x_{k_i+1})>\epsilon$. By \eqref{Eq:succ_gap_convergence} and the continuity of $\Psi\circ\nabla\phi^*$, we have that $\lim_{i\rightarrow\infty}\Psi(x_{k_i})=\lim_{i\rightarrow\infty}\Psi(x_{k_i+1})=\epsilon$. Recall that $x^{\lambda_\eta(k_i)}(0)=x_{k_i}$, therefore, $\Psi(\bar x(0))=\lim_{i\rightarrow\infty}\Psi(x_{k_i})=\epsilon$. Since $\bar x(0)$ is not in the stable set, there exists $T>0$, such that  
\[
\Psi(\bar x(T))<\sup_{s\in[0,T]}\Psi(\bar x(s))\leq\Psi(\bar x(0))=\epsilon.
\]
Then, there exists $\delta>0$, such that $\Psi(\bar x(T))\leq\epsilon-2\delta$. Moreover, for sufficiently large $i$, we have
\[
\sup_{s\in[0,T]}\Psi(x^{\lambda_\eta(k_i)}(s))\leq\sup_{s\in[0,T]}\Psi(\bar x(s))+\sup_{s\in[0,T]}|\Psi(x^{\lambda_\eta(k_i)}(s))-\Psi(\bar x(s))|\leq2\epsilon.
\]
The last inequality comes from the uniform convergence of $\{\nabla\phi(x^{\lambda_\eta(k_i)}(\cdot))\}$ in $\cC(\R_+,\R^n)$. This implies that for all large $i$, $\{x(\lambda_\eta(k_i)+s):s\in[0,T]\}\subset\cL_{2\epsilon}$. Thus it holds that $\lambda_\eta(j_i)>\lambda_\eta(k_i)+T$. Let $l_i=\max\{m:\lambda_\eta(k_i)\leq \lambda_\eta(m)\leq \lambda_\eta(k_i)+T\}$. Then $\|\nabla\phi(x_{l_i})-\nabla\phi(x^{\lambda_\eta(k_i)}(T))\|\leq\|\nabla\phi(x_{l_i})-\nabla\phi(x_{l_i+1})\|\rightarrow0$, and hence $\norm{\nabla\phi(x_{l_i})-\nabla\phi(\bar x(T))}\rightarrow0$ {as $i\to\infty$}. By the continuity of $\Psi\circ\nabla\phi^*$, we have that $\Psi(x_{l_i})\leq\epsilon-\delta$ for all large $i$. By the definition of $k_i$ and $j_i$, we have that $\lambda_\eta(j_i)<\lambda_\eta(l_i)\leq\lambda_\eta(k_i)+T$, which leads to a contradiction. Therefore, for all large $k$, $\Psi(x_k)\leq2\epsilon$. Since $\epsilon$ can be chosen arbitrarily small, it holds that $\lim_{k\rightarrow\infty}\Psi(x_k)=0$. This completes the proof.
\end{proof}

