\begin{definition}\label{Bregman-distance-def}
(Kernel function and Bregman distance over $\R^n$).  A function $\phi:\R^n\rightarrow\R$ is called a kernel function over $\R^n$, if $\phi$ is convex and $\phi\in\cC^1(\R^n)$. The Bregman distance \cite{bregman1967relaxation} generated by $\phi$ is denoted as $\cD_\phi(x,y):\R^n\times\R^n\rightarrow[0,+\infty)$, where
\[
\cD_\phi(x,y)=\phi(x)-\phi(y)-\inprod{\nabla\phi(y)}{x-y}.
\]
\end{definition}

\begin{definition}\label{Legendre}
(Legendre kernel over $\R^n$). Let $\phi$ be a kernel function over $\R^n$, such that $\lim_{k\rightarrow\infty}\|\nabla\phi({x_k})\|=\infty$ whenever $\{{x_k}\}_{k\in\mathbb N}$ satisfies $\lim_{k\rightarrow\infty}\norm{x_k}=\infty$. The function $\phi$ is called a Legendre function over $\R^n$ if it is also {strictly} convex on $\R^n$.
\end{definition}

\begin{equation}
    \label{Eq:Breg_DI}
    \frac{d}{dt}\nabla\phi(x(t))\in-\mathcal{H}(x(t)), \text{ for almost all $t\geq0$.}
\end{equation}

Any absolutely continuous solution to \eqref{Eq:Breg_DI} is termed a trajectory of \eqref{Eq:Breg_DI}. The stable set of \eqref{Eq:Breg_DI} is defined as 
\begin{equation}
\label{eq:def_stable_set}
\cH^{-1}(0):=\{x\in\R^n:0\in\cH(x)\}.
\end{equation}

