\begin{assumption}
\label{Assumption: DI}
    \begin{enumerate}
        \item {$\phi$ is a supercoecive Legendre kernel function over $\R^n$}, and $\nabla\phi$ is differentiable almost everywhere.
        \item The sequences $\{x_k\}$, $\{\nabla\phi(x_k)\}$ and $\{d_k\}$ are uniformly bounded.
        \item The stepsize $\{\eta_k\}$ satisfies $\sum_{k=0}^\infty\eta_k=\infty$ and $\lim_{k\rightarrow\infty}\eta_k=0$.
        \item For any $T>0$, the noise sequence $\{\xi_k\}$ satisfies 
        \begin{equation}
            \lim_{s\rightarrow\infty}\sup_{s\leq i\leq\Lambda_\eta(\lambda_\eta(s)+T)}\norm{\sum_{k=s}^i\eta_k\xi_k}=0.
            \label{Eq:noise_cond}
        \end{equation}       
        \item The set-valued mapping $\mathcal{H}$ has a closed graph. Additionally, for any unbounded increasing sequence $\{k_j\}$ such that $\{x_{k_j}\}$ converges to $\bar x$, it holds that 
        \begin{equation}
            \lim_{N\rightarrow\infty}{\rm dist}\left(\frac{1}{N}\sum_{j=1}^Nd_{k_j},\mathcal{H}(\bar x)\right)=0.
        \end{equation}
    \end{enumerate}
\end{assumption}

\begin{assumption}\label{assumption_Sard_Lyapunov}
 There exists a continuous function $\Psi:\R^n\to\R$, such that the following conditions hold:
 \begin{enumerate}
     \item (Weak Morse-Sard). The set 
     {$\{\Psi(x): \mbox{for $x$ such that $0\in\cH(x)$} \}$}  has empty interior in $\R$.
     \item (Lyapunov function). $\Psi$ is lower bounded, i.e. $\liminf_{x\in\R^n}\Psi(x)>-\infty$. For any trajectory $z(t)$ of the differential inclusion \eqref{Eq:Breg_DI} with $z(0)\notin\cH^{-1}(0)$,  there exists $T > 0$ such that
     \[
     \Psi(z(T))<\sup_{t\in[0,T]}\Psi(z(t))\leq\Psi(z(0)).
     \]
 \end{enumerate}
\end{assumption}

\begin{remark}
    \label{rmk:assumption_DI}
    \begin{enumerate}
        \item {If the Legendre function $\phi$ is supercoecive, i.e. $\lim_{\|u\|\rightarrow\infty}\frac{\phi(u)}{\|u\|}=\infty$, then by \cite[Theorem 26.5,\,Corollary 13.3.1]{rockafellar1997convex}, $\phi^*\in\cC^1(\R^n)$ is strictly convex, and $(\nabla\phi)^{-1}=\nabla\phi^*$.}
        \item Uniform boundedness of either $\{x_k\}$ or $\{\nabla\phi(x_k)\}$ may suffice under mild conditions. For example, if $\phi$ is locally strongly convex, then the uniform boundedness of $\{\nabla\phi(x_k)\}$ implies the uniform boundedness of $\{x_k\}$. Conversely, if $\nabla\phi$ is locally Lipschitz continuous, then the uniform boundedness of $\{x_k\}$ leads to the uniform boundedness of $\{\nabla\phi(x_k)\}$.
        \item For a martingale difference noise sequence $\{\xi_k\}$,  i.e. $\E[\xi_{k+1}|\cF_k]=0$ holds  almost surely,  as shown in \cite{benaim2005stochastic}, \eqref{Eq:noise_cond} can be ensured almost surely under one of the following conditions:
        \begin{enumerate}
            \item Uniform boundedness of $\{\xi_k\}$ with $\eta_k=o\left(\frac{1}{\log k}\right)$ as utilized in \cite{castera2021inertial,xiao2023adam,xiao2023convergence}.
            \item Variance-bounded $\{\xi_k\}$, i.e. $\E[\norm{\xi_{k+1}}^2|\cF_k]\leq\sigma^2$ for some $\sigma>0$, and square-summable $\{\eta_k\}$, i.e. $\sum_{k=0}^\infty\eta_k^2<\infty$, as employed in \cite{davis2020stochastic}.
        \end{enumerate}
        \item Assumption \ref{Assumption: DI}(5) describes how $d_k$ approximates $\cH(x_k)$. This assumption is quite mild. A sufficient condition for it hold is that $d_k\in\cH^{\delta_k}(x_k)$ with $\lim_{k\to\infty}\delta_k=0$. 
    \end{enumerate}
\end{remark}
